head.script:
scwin.trigger1_onclick = function(e) {
	var rowJSON = {
		"addr": "서울시",
		"name": "손예진",
		"rowStatus": "R"
	};
	var dataObj = {
		type: "json",
		data: rowJSON,
		name: "paramTest"
	};
	var options = {
		id: "popup1",
		type: "wframePopup",
		width: 300 + "px",
		height: 300 + "px",
		top: 100 + "px",
		left: 100 + "px",
		popupName: "Test111",
		modal: true,
		style: "",
		resizable: true,
		status: false,
		menubar: false,
		scrollbars: false,
		title: false,
		useMaximize: true,
		dataObject: dataObj
	};
	$p.openPopup("/sample/common_link/p_wframePopup_WPFF-331_(WSQ-3821)_main_sub.xml", options);
};
scwin.checkVal = function() {
	return localStorage.getItem('log') == '서울시';
}
scwin.onpageload = function() {
	localStorage.removeItem("log");
};
